message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a pale background with small tufts of grass under its feet. It has the overall body shape, dense shaggy fur, head and paws of a brown bear, with dark brown fur on the back, head and limbs and paler cream-tan fur on the muzzle, chest and belly. A single long, glossy, dark reddish-black curved horn projects upward and forward from the center of its forehead, and multiple large, shiny, dark reddish-brown chitinous plates resembling beetle elytra are set into the fur on the neck, back, sides, hips and outer leg joints. A row of six small oval black openings is visible in the light fur on the lower side beneath the largest lateral plate.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, lighter tan fur on the muzzle and around the mouth, a large black nose at the tip of the snout, small dark brown eyes on the side of the face, and a closed mouth with a visible lower lip and whiskers",
      "where": "at the front of the body facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark brown to black horn tapering to a sharp point and curving upward and forward, with two small pointed tooth-like projections on the inner concave edge near the tip and a thick base embedded in the fur of the forehead",
      "where": "arising from the midline of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur with slightly darker edges",
      "where": "on top of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs covered in long shaggy dark brown fur that is lighter on the inner chest and belly",
      "where": "two forelegs under the chest and shoulders and two hind legs under the hips supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark fur and five visible light tan curved claws on each paw that contact the ground",
      "where": "at the distal ends of the four legs"
    },
    {
      "part": "plates",
      "looks_like": "multiple large glossy dark reddish-brown chitinous plates with segmented transverse ridges and bright specular highlights, resembling beetle wing covers; includes two narrow curved plates on the lower neck/shoulder, two small oval plates on the upper back, one very large rectangular segmented plate on the mid-side, one large curved segmented plate on the hip, and one smaller rounded plate on the outer joint of each visible leg; the light fur directly below the large mid-side plate shows a row of six small vertically oval black openings",
      "where": "distributed across the dorsal and lateral surfaces of the neck, back, sides, hips and outer leg joints, set into the fur"
    },
    {
      "part": "markings",
      "looks_like": "paler cream to light tan fur contrasting with the darker brown fur",
      "where": "on the muzzle, lower jaw, chest and belly/underside"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
